<?php require_once __DIR__.'/alumno_common.php'; $stmt=$pdo->prepare("SELECT i.id AS inscripcion,i.estatus,m.nombre AS materia,m.clave,m.creditos,g.nombre AS grupo,pe.nombre AS periodo,p.nombre AS profesor FROM inscripciones i JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN grupos g ON g.id=mp.grupo JOIN periodos_escolares pe ON pe.id=g.id_periodo JOIN profesores p ON p.id=mp.profesor WHERE i.alumno=? ORDER BY pe.fecha_inicio DESC,m.nombre");$stmt->execute([$alumnoActual['id']]);$materias=$stmt->fetchAll(); alumno_layout('Materias e inscripciones','Materias y grupos vinculados a tu registro','materiasInscripciones.html',compact('materias'));
